const defaults = {
    maxDurationSec: 30,
    cooldownSec: 120,
    soilMoistureLowPct: 35,
    autoDurationSec: 10
};
const config = { ...defaults, ...(global.get('config') || {}) };
config.autoIrrigation = env.get('GW_AUTO_IRRIGATION') !== 'false';
global.set('config', config);
global.set('cloudUp', false);
node.status({ fill: 'grey', shape: 'dot', text: `gateway ${env.get('GW_ID')}` });
return null;

let m;
try {
    m = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('invalid JSON from the field node');
    return null;
}

const gw = env.get('GW_ID');
const now = Date.now();
global.set('fieldNodeSeenAt', now);

switch (m.type) {
    case 'hello': {
        node.log(`field node ${m.deviceId} connected (firmware ${m.firmware})`);
        const config = global.get('config') || {};
        const reply = { payload: JSON.stringify({ type: 'config', maxDurationSec: config.maxDurationSec, now: Date.now() }) };
        return [null, null, reply, null];
    }
    case 'telemetry': {
        const ts = m.ts > 1700000000000 ? m.ts : now;
        const readings = (m.readings || []).filter(r => r && r.type && typeof r.value === 'number');
        if (readings.length === 0) return null;
        global.set('latest', { ts, deviceId: m.deviceId, pump: m.pump, readings });
        node.status({ fill: 'green', shape: 'dot', text: `${readings.length} readings at ${new Date(ts).toLocaleTimeString()}` });
        const uplink = {
            topic: `greenpilot/${gw}/up/telemetry`,
            payload: {
                msgId: `${gw}-${m.deviceId}-${ts}`,
                deviceId: m.deviceId,
                ts: new Date(ts).toISOString(),
                readings
            }
        };
        return [uplink, { payload: readings }, null, null];
    }
    case 'ack': {
        if (m.status === 'COMPLETED' || m.status === 'ACCEPTED') global.set('lastWateringAt', now);
        if (String(m.commandId).startsWith('local-')) {
            node.log(`local irrigation ${m.commandId}: ${m.status}${m.reason ? ' (' + m.reason + ')' : ''}`);
            return null;
        }
        const ack = {
            topic: `greenpilot/${gw}/up/cmd-ack`,
            correlationData: Buffer.from(String(m.commandId)),
            payload: { commandId: m.commandId, status: m.status, reason: m.reason }
        };
        return [ack, null, null, null];
    }
    case 'event': {
        if (m.name === 'lowWater') node.warn(m.value ? 'reservoir empty' : 'reservoir refilled');
        return [null, null, null, { payload: JSON.stringify({ event: m.name, data: m.value, ts: new Date(now).toISOString() }) }];
    }
    default:
        return null;
}

const config = global.get('config') || {};
if (!config.autoIrrigation) return null;

const readings = msg.payload;
const reservoir = readings.find(r => r.type === 'reservoir');
if (!reservoir || reservoir.value !== 1) return null;

const dry = readings.filter(r => r.type === 'soil_moisture' && r.value < config.soilMoistureLowPct);
if (dry.length === 0) return null;

const now = Date.now();
if (now - (global.get('lastWateringAt') || 0) < config.cooldownSec * 1000) return null;
global.set('lastWateringAt', now);

const durationSec = Math.min(config.autoDurationSec, config.maxDurationSec);
const zones = dry.map(r => r.zoneId).join(', ');
node.log(`zone ${zones} below ${config.soilMoistureLowPct}%: local irrigation for ${durationSec} s`);
node.status({ fill: 'blue', shape: 'dot', text: `watered zone ${zones} at ${new Date(now).toLocaleTimeString()}` });
return {
    payload: JSON.stringify({
        type: 'command',
        commandId: `local-${now}`,
        action: 'IRRIGATE',
        durationSec,
        expiresAt: now + 30000
    })
};

const MAX_BUFFERED = 5000;

if (msg.status) {
    const up = msg.status.fill === 'green';
    const wasUp = global.get('cloudUp') === true;
    global.set('cloudUp', up);
    if (up && !wasUp) {
        const outbox = global.get('outbox') || [];
        global.set('outbox', []);
        node.status({ fill: 'green', shape: 'dot', text: 'cloud connected' });
        if (outbox.length > 0) {
            node.log(`cloud reachable again: sending ${outbox.length} buffered messages`);
            return [outbox.map(m => ({ topic: m.topic, payload: m.payload }))];
        }
    } else if (!up && wasUp) {
        node.warn('cloud unreachable: buffering messages');
        node.status({ fill: 'red', shape: 'ring', text: 'cloud unreachable' });
    }
    return null;
}

if (global.get('cloudUp') === true) return msg;

const outbox = global.get('outbox') || [];
outbox.push({ topic: msg.topic, payload: msg.payload });
if (outbox.length > MAX_BUFFERED) outbox.shift();
global.set('outbox', outbox);
node.status({ fill: 'yellow', shape: 'ring', text: `${outbox.length} messages buffered` });
return null;

const gw = env.get('GW_ID');
const cmd = msg.payload;
if (!cmd || typeof cmd !== 'object' || !cmd.commandId) {
    node.warn('command without commandId ignored');
    return null;
}

const ackTopic = msg.responseTopic || `greenpilot/${gw}/up/cmd-ack`;
const ack = (status, reason) => ({
    topic: ackTopic,
    correlationData: msg.correlationData || Buffer.from(cmd.commandId),
    payload: { commandId: cmd.commandId, status, reason }
});

const now = Date.now();
const seen = global.get('seenCommands') || {};
for (const id of Object.keys(seen)) {
    if (now - seen[id] > 24 * 3600 * 1000) delete seen[id];
}
if (seen[cmd.commandId]) {
    node.warn(`duplicate command ${cmd.commandId} ignored`);
    return null;
}
seen[cmd.commandId] = now;
global.set('seenCommands', seen);

const expiresAt = Date.parse(cmd.expiresAt) || 0;
if (expiresAt && expiresAt < now) return [null, ack('REJECTED', 'command expired before reaching the gateway')];

const config = global.get('config') || {};
node.log(`command ${cmd.action} ${cmd.commandId}`);

switch (cmd.action) {
    case 'IRRIGATE': {
        if (now - (global.get('fieldNodeSeenAt') || 0) > 90000) return [null, ack('REJECTED', 'field node offline')];
        const latest = global.get('latest');
        const reservoir = latest && latest.readings.find(r => r.type === 'reservoir');
        if (!reservoir || reservoir.value !== 1) return [null, ack('REJECTED', 'reservoir empty')];
        if (!(cmd.durationSec >= 1 && cmd.durationSec <= config.maxDurationSec)) {
            return [null, ack('REJECTED', `duration must be between 1 and ${config.maxDurationSec} s`)];
        }
        const forward = {
            type: 'command',
            commandId: cmd.commandId,
            action: 'IRRIGATE',
            durationSec: cmd.durationSec,
            expiresAt
        };
        return [{ payload: JSON.stringify(forward) }, null];
    }
    case 'UPDATE_CONFIG': {
        const irrigation = cmd.irrigation || {};
        const thresholds = cmd.thresholds || {};
        const next = { ...config };
        if (irrigation.maxDurationSec) next.maxDurationSec = irrigation.maxDurationSec;
        if (irrigation.cooldownSec) next.cooldownSec = irrigation.cooldownSec;
        if (typeof thresholds.soilMoistureLowPct === 'number') next.soilMoistureLowPct = thresholds.soilMoistureLowPct;
        global.set('config', next);
        const toField = { payload: JSON.stringify({ type: 'config', maxDurationSec: next.maxDurationSec, now: Date.now() }) };
        return [toField, ack('COMPLETED')];
    }
    case 'DEPLOY_MODEL':
        return [null, ack('REJECTED', 'no model runtime on this gateway yet')];
    default:
        return [null, ack('REJECTED', `unknown action ${cmd.action}`)];
}

const now = Date.now();
msg.payload = {
    gatewayId: env.get('GW_ID'),
    cloudConnected: global.get('cloudUp') === true,
    fieldNodeOnline: now - (global.get('fieldNodeSeenAt') || 0) < 90000,
    bufferedMessages: (global.get('outbox') || []).length,
    config: global.get('config'),
    latest: global.get('latest') || null
};
return msg;

const td = JSON.parse(JSON.stringify(global.get('thingDescription')));
const host = msg.req.headers.host;
td.base = `http://${host}/`;
for (const event of Object.values(td.events || {})) {
    for (const form of event.forms) form.href = form.href.replace('{host}', host);
}
msg.payload = td;
msg.headers = { 'Content-Type': 'application/td+json' };
return msg;

const latest = global.get('latest');
const find = (type, zoneId) => {
    if (!latest) return undefined;
    const r = latest.readings.find(x => x.type === type && (zoneId === undefined || x.zoneId === zoneId));
    return r ? r.value : undefined;
};
const water = find('reservoir');
const values = {
    soilMoistureA: find('soil_moisture', 'A'),
    soilMoistureB: find('soil_moisture', 'B'),
    airTemperature: find('air_temperature'),
    airHumidity: find('air_humidity'),
    waterAvailable: water === undefined ? undefined : water === 1,
    pumpState: latest ? latest.pump : undefined
};

const name = msg.req.params.name;
if (!(name in values)) {
    msg.statusCode = 404;
    msg.payload = { error: `unknown property ${name}` };
} else if (values[name] === undefined) {
    msg.statusCode = 503;
    msg.payload = { error: 'no reading received from the field node yet' };
} else {
    msg.payload = JSON.stringify(values[name]);
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const config = global.get('config') || {};
const durationSec = Number(msg.payload && msg.payload.durationSec);
const now = Date.now();
const latest = global.get('latest');
const reservoir = latest && latest.readings.find(r => r.type === 'reservoir');

let error;
if (!Number.isInteger(durationSec) || durationSec < 1 || durationSec > config.maxDurationSec) {
    error = [400, `durationSec must be an integer between 1 and ${config.maxDurationSec}`];
} else if (now - (global.get('fieldNodeSeenAt') || 0) > 90000) {
    error = [503, 'field node offline'];
} else if (!reservoir || reservoir.value !== 1) {
    error = [409, 'reservoir empty'];
} else if (now - (global.get('lastWateringAt') || 0) < config.cooldownSec * 1000) {
    error = [409, 'cooldown active'];
}
if (error) {
    msg.statusCode = error[0];
    msg.payload = { error: error[1] };
    return [msg, null];
}

const commandId = `local-${now}`;
global.set('lastWateringAt', now);
msg.statusCode = 202;
msg.payload = { commandId, status: 'SENT' };
const command = { payload: JSON.stringify({ type: 'command', commandId, action: 'IRRIGATE', durationSec, expiresAt: now + 30000 }) };
return [msg, command];
